script:
import json,sys,subprocess,os,hashlib,shutil
from pathlib import Path
repo=Path.cwd();base=repo/'benchmarks/native-preflight-20261002'
base.mkdir(exist_ok=False)
(base/'scene.mjs').write_text("import * as THREE from "/three.webgpu.js";
const renderer = new THREE.WebGPURenderer({ antialias: true, alpha: false, forceWebGL: false });
renderer.setPixelRatio(1);
renderer.setSize(800, 800);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1;
document.body.appendChild(renderer.domElement);
await renderer.init();
if (renderer.backend.isWebGPUBackend !== true) throw new Error("Native WebGPU backend required");
const scene = new THREE.Scene();
scene.background = new THREE.Color(0xd9dfdf);
const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 100);
camera.position.set(5, 4, 6); camera.lookAt(0, 0.4, 0);
scene.add(new THREE.HemisphereLight(0xddefff, 0x8a765d, 2));
const sun = new THREE.DirectionalLight(0xffefd7, 3);
sun.position.set(-3, 7, 5); scene.add(sun);
const ground = new THREE.Mesh(new THREE.BoxGeometry(6, 0.2, 6), new THREE.MeshStandardMaterial({color:0x819b66, roughness:1}));
ground.position.y=-0.6;scene.add(ground);
const cube = new THREE.Mesh(new THREE.BoxGeometry(1.5,1.5,1.5),new THREE.MeshStandardMaterial({color:0xd78352,roughness:0.8}));
cube.position.y=0.25;cube.rotation.y=0.35;scene.add(cube);
for(let i=0;i<3;i++) await renderer.renderAsync(scene,camera);
globalThis.__BENCHMARK_NATIVE_READY__={ok:true,engine:"three.js",revision:THREE.REVISION,backend:"WebGPU",classification:"native-render preflight only",sceneObjects:2};
")
(base/'run.mjs').write_text("import {createServer} from "node:http";
import {readFile,mkdir} from "node:fs/promises";
import {resolve,dirname} from "node:path";
import {fileURLToPath} from "node:url";
import {runVerifiedScene} from "../../scripts/verified-webgpu.mjs";
const dir=dirname(fileURLToPath(import.meta.url));
const repo=resolve(dir,"../..");
const out=resolve(dir,"attempt-001");await mkdir(out,{recursive:true});
const routes=new Map([
["/scene.mjs",[resolve(dir,"scene.mjs"),"text/javascript"]],
["/three.webgpu.js",[resolve(repo,"shadow-lab/src/compare/three.webgpu.js"),"text/javascript"]],
["/three.core.js",[resolve(repo,"shadow-lab/src/compare/three.core.js"),"text/javascript"]]
]);
const server=createServer(async(req,res)=>{
res.setHeader("Cross-Origin-Opener-Policy","same-origin");res.setHeader("Cross-Origin-Embedder-Policy","require-corp");
if(req.url==="/favicon.ico"){res.writeHead(204);res.end();return}
if(req.url==="/"){res.setHeader("Content-Type","text/html");res.end('<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0}</style></head><body><script type="module" src="/scene.mjs"></script></body></html>');return}
const entry=routes.get(req.url);
if(!entry){res.writeHead(404);res.end("Not found");return}
try{res.setHeader("Content-Type",entry[1]);res.end(await readFile(entry[0]));}catch{res.writeHead(500);res.end("Read error")}
});
await new Promise((ok,fail)=>{server.once("error",fail);server.listen(0,"127.0.0.1",ok)});
try{
const r=await runVerifiedScene({runtimeRoot:process.env.APERTURE_WEBGPU_RUNTIME,scratchRoot:process.env.APERTURE_TMP_RUN,url:`http://127.0.0.1:${server.address().port}/`,outputPath:resolve(out,"result.json"),screenshotPath:resolve(out,"render.png"),readyGlobal:"__BENCHMARK_NATIVE_READY__",viewport:{width:800,height:800}});
console.log(JSON.stringify({status:r.status,scene:r.sceneStatus,proof:r.proof}));
}finally{server.closeAllConnections();await new Promise(ok=>server.close(ok))}
")
ref=Path('/workspace/scratch/0190a8c72f8a/generated_images/exec-76bd9f8b-ca2f-462f-9a69-f25949fe8fa5.png')
shutil.copyfile(ref,base/'preserved-cottage-reference.png')
files=[repo/'shadow-lab/src/compare/three.webgpu.js',repo/'shadow-lab/src/compare/three.core.js',base/'scene.mjs',base/'run.mjs',base/'preserved-cottage-reference.png']
pins={'schema':1,'purpose':'Verify three.js native WebGPU before the independent paired author benchmark; no comparative score','aperture_source':'2c89bd7b1ea6583b990a9745ba9fa4cbf7f28c33','three_revision':'185dev (actual vendored source; not the r184 label in an older formatting comment)','files':{str(p.relative_to(repo)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files},'reference':'Preserved generated low-poly cottage reference from the prior workspace; retained bytes, not regenerated'}
(base/'pins.json').write_text(json.dumps(pins,indent=2)+'
')
subprocess.run(['node','--check',str(base/'scene.mjs')],check=True)
subprocess.run(['node','--check',str(base/'run.mjs')],check=True)
print(json.dumps({'free_bytes_before':shutil.disk_usage('/workspace/scratch/0190a8c72f8a/aperture-tmp').free}),flush=True)
env=os.environ.copy();env['APERTURE_WEBGPU_RUNTIME']=str(repo/'.aperture-env/render-runtime')
cmd=['python3','-B','tools/recovery/runtime_pressure.py','--root','/workspace/scratch/0190a8c72f8a/aperture-tmp','--audit-dir',str(base/'lifecycle-audits'),'run','--job','three-native-preflight','--recreation','Run the pinned preflight through runVerifiedScene','--','node',str(base/'run.mjs')]
with (base/'attempt-001-tool-output.log').open('xb') as log:
 proc=subprocess.Popen(cmd,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 for line in proc.stdout:
  log.write(line);log.flush();sys.stdout.buffer.write(line);sys.stdout.buffer.flush()
 raise SystemExit(proc.wait())
